import numpy as np
from sklearn.cluster import KMeans
from sklearn.metrics import normalized_mutual_info_score

from src.proximity_kernel import build_representation


def evaluate_representation(Z, y, k, seeds):
    scores = []
    for seed in seeds:
        km = KMeans(n_clusters=k, init="k-means++", n_init=10, random_state=int(seed))
        labels = km.fit_predict(Z)
        scores.append(float(normalized_mutual_info_score(y, labels)))
    arr = np.array(scores, dtype=float)
    return float(arr.mean()), float(arr.std(ddof=0)), scores


def search_nbins(X, y, k, nbins_grid, seeds):
    results = {}
    best_nbins = None
    best_mean = -1.0
    diagnostics_by_nbins = {}
    for nb in nbins_grid:
        Z, diag = build_representation(X, int(nb))
        mean, std, scores = evaluate_representation(Z, y, k, seeds)
        results[int(nb)] = {"mean_nmi": mean, "std_nmi": std, "per_seed": scores, "z_shape": list(Z.shape)}
        diagnostics_by_nbins[int(nb)] = diag
        if mean > best_mean:
            best_mean = mean
            best_nbins = int(nb)
    return best_nbins, best_mean, results, diagnostics_by_nbins

